"""Build the standalone review board from local card data and illustrations."""
from pathlib import Path
import base64
import html
import json

ROOT = Path(__file__).resolve().parent
PROJECT = ROOT.parent.parent
cards = json.loads((ROOT / 'cards.json').read_text())
esc = html.escape

def data_uri(path, mime):
    return f'data:{mime};base64,' + base64.b64encode(path.read_bytes()).decode()

fonts = '\n'.join(f"@font-face{{font-family:'{name}';src:url({data_uri(PROJECT / 'public/art' / filename, 'font/ttf')}) format('truetype');font-weight:{weight};font-display:swap}}" for name, filename, weight in [('Bitcount', 'bitcount-prop-single.ttf', '400'), ('Lexend', 'lexend.ttf', '100 900')])
style = '''
*{box-sizing:border-box}html{color-scheme:dark;scroll-behavior:smooth}body{margin:0;background:#14112a;color:#f6f2ff;font:400 14px/1.6 Lexend,system-ui,sans-serif;background-image:linear-gradient(#d6a5ff0b 1px,transparent 1px),linear-gradient(90deg,#d6a5ff0b 1px,transparent 1px);background-size:24px 24px}a{color:inherit;text-underline-offset:4px}:focus-visible{outline:3px solid #68f2d0;outline-offset:5px}main{max-width:1260px;margin:auto;padding:26px 28px 50px}.topline{display:flex;justify-content:space-between;gap:16px;align-items:center;padding-bottom:22px;border-bottom:1px solid #706298}.brand{font:24px Bitcount,monospace}.brand span{background:#68f2d0;color:#14112a;padding:3px 7px;margin-right:8px}.version{font-size:11px;letter-spacing:.1em;color:#ffd284;text-transform:uppercase}.intro{display:flex;gap:28px;justify-content:space-between;align-items:flex-end;margin:34px 0 24px}.eyebrow{text-transform:uppercase;letter-spacing:.14em;font-size:10px;color:#ffd284;font-weight:600;margin:0 0 10px}h1,h2{font-family:Bitcount,monospace;font-weight:400;line-height:1.08;margin:0}h1{font-size:clamp(36px,5.5vw,64px);max-width:850px}.intro p:not(.eyebrow){color:#c6bcd9;max-width:650px;margin:13px 0 0}.collection-mark{border:1px solid #706298;padding:12px 18px;text-align:center;flex-shrink:0;color:#c6bcd9;font-size:11px}.collection-mark b{display:block;font:38px Bitcount,monospace;color:#ffd284}.timeline{display:flex;gap:8px;flex-wrap:wrap;margin:0 0 27px}.timeline a{font-size:11px;text-decoration:none;padding:6px 10px;border:1px solid #514568;background:#211a36;color:#d8cfe8}.timeline a:hover{border-color:#ffd284;color:#ffd284}.gallery{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px;align-items:stretch}.card{position:relative;display:flex;flex-direction:column;min-width:0;padding:17px;background:linear-gradient(145deg,#33264e,#18162f 65%);box-shadow:inset 0 0 0 6px #ffd284,inset 0 0 0 9px #18162f,inset 0 0 0 10px #dd83b9;clip-path:polygon(17px 0,calc(100% - 17px) 0,100% 17px,100% calc(100% - 17px),calc(100% - 17px) 100%,17px 100%,0 calc(100% - 17px),0 17px)}.card-top{display:flex;justify-content:space-between;align-items:center;color:#ffd284;letter-spacing:.12em;text-transform:uppercase;font-size:10px;padding:1px 3px 11px}.card-top span:last-child{font-family:Bitcount,monospace;font-size:16px}.art{width:100%;height:auto;aspect-ratio:1;object-fit:cover;border:1px solid #dd83b9;display:block}.copy{padding:16px 4px 5px;display:flex;flex:1;flex-direction:column}.era{font-size:10px;text-transform:uppercase;letter-spacing:.075em;color:var(--accent);margin:0 0 8px}h2{font-size:29px;color:#ffd284;overflow-wrap:anywhere}.catalogue{font-size:10px;color:#bdb2d2;line-height:1.5;min-height:30px;margin:7px 0 13px}.composer{font-size:13px;font-weight:600;margin:0 0 10px}.date{display:flex;gap:10px;align-items:baseline;border-top:1px solid #514568;border-bottom:1px solid #514568;padding:9px 0;margin-bottom:13px}.date b{font:21px Bitcount,monospace;color:#ffd284;white-space:nowrap}.date small{color:#c6bcd9;font-size:9px;line-height:1.5}.description{font-size:12px;margin:0 0 15px}.prompt{border-left:2px solid var(--accent);padding-left:10px;font-size:10px;color:#d9d0e6;margin:0 0 19px}.prompt span{display:block;font-size:9px;text-transform:uppercase;letter-spacing:.08em;color:var(--accent);margin-bottom:4px}.recording{margin-top:auto}.recording small{display:block;font-size:9px;color:#bdb2d2;margin-bottom:7px}.spotify{display:flex;align-items:center;justify-content:space-between;gap:10px;text-decoration:none;border:1px solid #68f2d0;color:#68f2d0;background:#68f2d00c;padding:10px 11px;min-height:44px;font-size:11px;font-weight:600}.spotify:hover{background:#68f2d0;color:#14112a}.spotify .play{font-size:13px}.footer{margin-top:28px;padding-top:19px;border-top:1px solid #514568;color:#bdb2d2;font-size:11px}.footer p{max-width:900px}.footer summary{cursor:pointer;color:#ffd284;min-height:36px;padding:5px 0}.sources{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px 22px;padding-left:20px}.sources a{color:#90c9ff}.notes{max-width:920px}.notes p{margin:9px 0}.prompts p{font-size:10px;overflow-wrap:anywhere}@media(min-width:1000px){.copy h2{min-height:63px}}@media(max-width:900px){.gallery{grid-template-columns:repeat(2,minmax(0,1fr))}.intro{align-items:flex-start}.collection-mark{display:none}}@media(max-width:590px){main{padding:18px 16px 32px}.brand{font-size:19px}.version{font-size:9px}.gallery{grid-template-columns:minmax(0,1fr);gap:22px}.intro{margin-top:26px}h1{font-size:40px}.copy{padding-top:16px}h2{font-size:31px}.description{font-size:13px}.catalogue{min-height:0}.sources{grid-template-columns:1fr}.timeline{gap:6px}.topline{gap:8px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}
'''
articles = []
for i, c in enumerate(cards, 1):
    image = data_uri(ROOT / 'assets' / (c['id'] + '.jpg'), 'image/jpeg')
    articles.append(f'''<article class="card" id="{c['id']}" style="--accent:{c['accent']}">
<div class="card-top"><span>✦ Karta specjalna</span><span>{i:02d} / 06</span></div>
<img class="art" src="{image}" alt="{esc(c['alt'])}" width="960" height="960">
<div class="copy"><p class="era">{esc(c['era'])}</p><h2>{esc(c['title'])}</h2>
<p class="catalogue">{esc(c['catalogue'])}</p><p class="composer">{esc(c['composer'])}</p>
<div class="date"><b>{esc(c['date'])}</b><small>Powstanie · {esc(c['dateNote'])}</small></div>
<p class="description">{esc(c['description'])}</p><p class="prompt"><span>Na tropie dźwięków</span>{esc(c['listenFor'])}</p>
<div class="recording"><small>Fortepian · {esc(c['performer'])}</small><a class="spotify" target="_blank" rel="noopener noreferrer" href="{c['spotify']}" aria-label="Posłuchaj w Spotify: {esc(c['title'])}, {esc(c['performer'])}"><span><span class="play" aria-hidden="true">▶</span> Posłuchaj w Spotify</span><span aria-hidden="true">↗</span></a></div>
</div></article>''')
links = ''.join(f'<li><a href="{esc(c["source"])}" target="_blank" rel="noopener noreferrer">{esc(c["composer"])} · {esc(c["sourceLabel"])}</a></li>' for c in cards)
nav = ''.join(f'<a href="#{c["id"]}">{esc(c["composer"].split()[-1])} · {esc(c["date"].split(" / ")[0])}</a>' for c in cards)
page = f'''<!doctype html><html lang="pl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Fortepianowe odkrycia · Edi’s Quest Log</title><style>{fonts}{style}</style></head><body><main>
<header class="topline"><div class="brand"><span>♪</span>Edi’s Quest Log</div><div class="version">Podgląd kolekcji · v1</div></header>
<section class="intro" aria-labelledby="heading"><div><p class="eyebrow">Album odkrywcy / Muzyka fortepianowa</p><h1 id="heading">Fortepianowe odkrycia</h1><p>Sześć utworów, sześć muzycznych światów. Poznaj kompozytorów, przyjrzyj się kartom i wyrusz na poszukiwanie dźwięków.</p></div><div class="collection-mark"><b>06</b>kart specjalnych</div></section>
<nav class="timeline" aria-label="Przejdź do karty kompozytora">{nav}</nav>
<section class="gallery" aria-label="Sześć nowych kart specjalnych">{''.join(articles)}</section>
<footer class="footer"><p>Ilustracje: ImageGen · oryginalne galaretkowe stworki w stylistyce nowszych kart zwykłych Edi’s Quest Log. Ilustracje są swobodnymi skojarzeniami z muzyką.</p>
<details><summary>Źródła i uwagi o utworach</summary><ol class="sources">{links}</ol><div class="notes"><p>Bach: rok 1722 dotyczy wersji w I tomie Das Wohltemperierte Klavier. To muzyka klawiszowa z epoki baroku, tu w wykonaniu fortepianowym.</p><p>Mozart: datowanie KV 331 jest przybliżone; najbardziej prawdopodobny jest rok 1783. „Marsz turecki” to trzecia część sonaty.</p><p>Chopin: cykl op. 28 ukończono na przełomie lat 1838–1839; część pomysłów pochodzi z wcześniejszych lat. <a href="https://chopin.nifc.pl/en/chopin/kompozycja/208" target="_blank" rel="noopener noreferrer">Katalog NIFC</a> podaje dla preludium szersze datowanie 1831(?)–1839. „Deszczowe” jest późniejszym przydomkiem.</p><p>Debussy: 1890 to data pierwszej wersji suity, a 1905 — ostatecznej redakcji i wydania. Tradycyjne określenie „impresjonizm” opisuje tu styl muzyki.</p><p>Joplin: 1902 to udokumentowany rok wydania; dokładnej daty kompozycji nie podajemy. Ragtime poszerza kolekcję o amerykański nurt muzyki fortepianowej. O popularności utworu i filmie „Żądło”: <a href="https://encyclopediaofarkansas.net/entries/scott-joplin-527/" target="_blank" rel="noopener noreferrer">Encyclopedia of Arkansas</a>.</p><p>Przyciski prowadzą do konkretnych nagrań Spotify, a nazwisko nad przyciskiem wskazuje pianistę.</p></div></details>
</footer></main></body></html>'''
output = ROOT.parent / 'karty-specjalne-fortepian-v1.html'
output.write_text(page)
print(f'Created {output.name}: {len(cards)} cards, {len(page):,} characters')
